import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"What do I need before I install the adapter?","description":"","frontmatter":{"order":1,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/01.erste-schritte/01.voraussetzungen.md"},"headers":[],"relativePath":"adapter/esphome/erste-schritte/voraussetzungen.md","filePath":"adapter/esphome/erste-schritte/voraussetzungen.md","lastUpdated":1795562976000}'),s={name:"adapter/esphome/erste-schritte/voraussetzungen.md"};function n(d,e,i,h,l,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="what-do-i-need-before-i-install-the-adapter" tabindex="-1">What do I need before I install the adapter? <a class="header-anchor" href="#what-do-i-need-before-i-install-the-adapter" aria-label="Permalink to &quot;What do I need before I install the adapter?&quot;">​</a></h1><p><a id="have-install-python-pip-myself"></a></p><h2 id="do-i-have-to-install-python-or-pip-myself" tabindex="-1">Do I have to install Python or pip myself? <a class="header-anchor" href="#do-i-have-to-install-python-or-pip-myself" aria-label="Permalink to &quot;Do I have to install Python or pip myself?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="systems-hardware-adapter-run"></a></p><h2 id="which-systems-and-hardware-does-the-adapter-run-on" tabindex="-1">Which systems and hardware does the adapter run on? <a class="header-anchor" href="#which-systems-and-hardware-does-the-adapter-run-on" aria-label="Permalink to &quot;Which systems and hardware does the adapter run on?&quot;">​</a></h2><p>The adapter runs on any system with ioBroker and Node.js 22.12 or newer. The integrated ESPHome Dashboard runs only on 64-bit Linux and macOS.</p><table tabindex="0"><thead><tr><th>What</th><th>Requirement</th></tr></thead><tbody><tr><td>Adapter with devices</td><td>Node.js 22.12 or newer, admin 7.8.20 or newer, js-controller 6.0.11 or newer</td></tr><tr><td>Integrated dashboard</td><td>additionally 64-bit Linux or macOS and internet access at startup</td></tr><tr><td>Dashboard with &quot;Use Docker Integration (Beta)&quot;</td><td>additionally Docker on the ioBroker host</td></tr></tbody></table><p>The adapter needs no Python for the devices, it talks to them directly through the Native API. Only the integrated dashboard needs Python. The adapter creates its own environment for it at startup, with Python 3.13.2 by default.</p><p>A Raspberry Pi with a 64-bit processor is still a 32-bit system if the operating system is installed in 32 bit. There the dashboard only starts after reinstalling with a 64-bit operating system.</p><h3 id="what-hardware-do-i-need" tabindex="-1">What hardware do I need? <a class="header-anchor" href="#what-hardware-do-i-need" aria-label="Permalink to &quot;What hardware do I need?&quot;">​</a></h3><p>Any hardware that runs ioBroker is enough for the devices. The dashboard compiles firmware, which needs a lot of CPU and memory. A Raspberry Pi 3 becomes very slow, a Raspberry Pi 4 runs stable. If your host is too weak or runs Windows, run the dashboard on another computer.</p><p><strong>See also:</strong> <a href="./../anleitungen/dashboard-nutzen#use-external-esphome-dashboard-instead">How do I use an external ESPHome dashboard instead of the built-in one?</a></p><p><a id="need-home-assistant-mqtt-use"></a></p><h2 id="do-i-need-home-assistant-or-mqtt-to-use-esphome-devices-in-iobroker" tabindex="-1">Do I need Home Assistant or MQTT to use ESPHome devices in ioBroker? <a class="header-anchor" href="#do-i-need-home-assistant-or-mqtt-to-use-esphome-devices-in-iobroker" aria-label="Permalink to &quot;Do I need Home Assistant or MQTT to use ESPHome devices in ioBroker?&quot;">​</a></h2><p><em>This section is still being written.</em></p>',16)])])}const c=t(s,[["render",n]]);export{u as __pageData,c as default};
